contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public {
        require(true);

        uint before = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterVal = c.MinSum(); if (__ESBMC_reverted()) return;

        assert((!reverted && afterVal == _val) || (reverted && afterVal == before));
    }

    receive() external payable {}
}

